window.DOSIK=window.DOSIK||{};DOSIK["mg_mgmt"]={"1":[{"t":"def","term":"경영","text":"조직의 목표를 성공적으로 달성하기 위해 · 조직의 모든 자원을 계획, 조직, 지휘, 통제 하는 과정을 말한다","ex":["영리를 추구하는 조직뿐만 아니라 비영리조직에도 경영의 개념이 필요하다","조직의 상층부에 속한 최고 의사결정자뿐만 아니라 조직의 모든 구성원을 대상으로 한다"]},{"t":"tree","title":"형태에 따른 경영자원","root":"경영자원","branches":[["유형","유형 자원"],["무형","무형 자원"],["인적","인적 자원"]]},{"t":"tree","title":"경영학 관점","root":"경영학","branches":[["통합·조정","전체적인 입장에서 통합ㆍ조정을 중시한다"],["총체적 흐름","기업 전체와 각 부서의 활동에 대한 총체적인 흐름을 파악한다"],["개방시스템","개방시스템 개념과 피드백 개념이 경영 발전에 중요한 영향을 미쳤다"],["환경 변화","기업환경 변화에 탄력적으로 적응할 수 있다"]]},{"t":"table","title":"기업·경영자 관련 설명","head":["대상","내용"],"rows":[["기업의 사회적 책임","자선적 책임은 경제적, 법적, 윤리적 책임과 관계없이 수행된다"],["전문경영자","소유경영자에 비해 단기적 기업이익을 추구하는 성향을 보인다"],["카츠(R. Katz)","개념적 기술은 최고경영층에게 가장 많이 요구된다"],["민쯔버그(Mintzberg)","경영자의 역할로 대인적, 정보전달적, 의사결정적 역할을 제시하였다"]]}],"2":[{"t":"tree","title":"경쟁우위와 자원","root":"경영전략의 경쟁우위","branches":[["사업부 수준 경쟁전략","원가우위 전략, 차별화 전략 등"],["학습곡선","기존 기업이 갖는 학습곡선은 새로운 경쟁자의 진입 비용을 높이는 역할을 한다"],["자원기반관점","보유자원의 특이성이 클수록 경쟁우위를 획득할 가능성이 크다"],["모방 곤란","조직문화, 고객과의 신뢰 등과 같이 인과관계의 모호성이 큰 자원일수록 모방이 어렵다"],["상대적 시장점유율","0.4라는 것은 자사 사업부의 시장점유율이 그 시장에서의 경쟁 기업 중 가장 큰 점유율을 나타내는 경쟁사 시장점유율의 2/5 수준임을 의미한다"],["핵심역량","고객에 대한 편익을 증대시킨다 · 경쟁사가 모방하기 어려운 독보적 능력이다 · 경쟁사를 능가하는 우월적 능력이다"]]},{"t":"def","term":"수직통합","text":"기업의 유통경로나 생산투입물의 공급원에 대한 소유나 통제를 도모하는 경영전략으로, 기업이 전방 혹은 후방으로 자사의 가치사슬 활동을 확대하고자 하는 것이다"},{"t":"vs","title":"전방통합과 후방통합","cols":[{"name":"전방수직통합","items":["기업 산출물에 대한 수요의 예측력을 높일 수 있다"]},{"name":"후방수직통합","items":["생산투입물에 대한 공급안정성을 높이고자 하는 경우 채택하게 된다"]}]}],"3":[{"t":"tree","title":"경영혁신 방법","root":"경영혁신","branches":[["조직개편","조직개편을 통해 조직을 단순화하고 군살을 뺀다"],["사업부문 매각","경쟁우위를 갖지 못하는 사업부문을 매각한다"],["인원 감축","불필요한 인원을 감축함으로써 경영효율성을 높인다"],["유휴시설","유휴생산시설을 줄임으로써 비용절감을 꾀한다"]]}],"4":[{"t":"def","term":"집단의사결정","text":"경영환경의 불확실성과 복잡성으로 인하여 집단의사결정이 개인의사결정보다 의사결 정의 질이 더 우월하다는 기본 가정하에서 이루어진다","ex":["대표적인 집단의사결정 기법으로 브레인스토밍, 델파이집단기법 등이 있다"]},{"t":"vs","title":"집단의사결정의 장단점","cols":[{"name":"장점","items":["의사결정의 결과에 대한 구성원의 수용가능성 증진"]},{"name":"단점","items":["소수의 구성원이 집단의사결정 과정을 지배하여 구성원들의 자유로운 의사표현이 방해를 받을 수 있다"]},{"name":"초기 결정 고수","items":["초기 결정이 잘못된 것을 알고도 그 결정을 고수하기 위해 인적ㆍ물적 자원을 지속적으로 제공하는 것을 말한다"]}]},{"t":"tree","title":"리더십 상황이론","root":"리더십 유형과 리더가 처한 상황의 적절한 조합","branches":[["리더 유형","리더의 유형을 과업지향적 리더와 관계지향적 리더로 구분하였다"],["상황 변수","리더와 구성원의 관계, 과업 구조, 지위 권력을 제시하였다"],["호의적 상황","상황이 리더에게 매우 호의적이면 과업지향적 리더가 더 좋은 성과를 보인다"]]},{"t":"table","title":"동기부여이론","head":["이론가","내용"],"rows":[["매슬로우(A. Maslow)","욕구단계이론에서 최상위 욕구는 자아실현욕구이다"],["맥클리랜드(D. McClelland)","성취동기이론은 성취욕구, 권력욕구, 친교욕구를 제시하여 동기부여를 설명한다"],["브룸(V. Vroom)","기대이론은 기대감, 수단성, 유의성을 동기부여의 요소로 제시한다"]]}],"5":[{"t":"table","title":"조직구조 유형","head":["조직","특징"],"rows":[["유기적 조직","과업공유와 분권화된 의사결정을 특징으로 하며 환경 변화에 신속히 대응할 수 있다"],["기계적 조직","공식화 정도가 높다"],["매트릭스 조직","한 명의 부하가 두 명의 상사에게 보고하며, 이중적 명령계통으로 인해 중첩되는 부문 간 갈등이 야기될 수 있다"],["기능식 조직","기능별 전문화, 규모의 경제 등을 추구하는 기업에 적합하다"],["가상 네트워크 조직","조정과 협력을 강조한다"],["위원회 조직","조직의 특정 과업 해결을 위해 조직의 일상적 업무 수행 기구와는 별도로 구성된 전문가 혹은 업무관계자들의 활동조직이다"]]},{"t":"def","term":"통제","text":"경영의 계획ㆍ조직ㆍ지휘 활동과 더불어 순환적으로 수행되어야 할 기본적인 기능이다","ex":["경영통제시스템은 조직의 목표 달성을 위해 사전에 설정된 표준에 조직의 성과를 일치시키고자 하는 것이다"]},{"t":"vs","title":"재무통제와 예산통제","cols":[{"name":"재무통제","items":["기업의 자산이 효율적으로 관리되고 있는지를 확인하는 것이다","최고경영층이 주로 사용한다"]},{"name":"예산통제","items":["중간경영층이 많이 사용 하는 통제기법이다"]}]}],"7":[{"t":"table","title":"재고 관련 비용","head":["비용","내용"],"rows":[["주문비용","주문할 때 발생하는 비용"],["가동준비비용","생산설비 가동준비에 소요되는 비용"],["품목비용","재고품목의 구매비용이나 생산비용"],["재고유지비용","보험료, 도난, 파손, 진부화 등과 관련된 비용"]]},{"t":"table","title":"품질관리 도구","head":["도구","활용"],"rows":[["흐름도","공정의 흐름을 묘사하는데 활용된다"],["특성요인도","개선하려는 문제의 잠재적 원인 규명에 활용된다"],["체크시트","품질특성의 발생 빈도를 기록하는데 활용된다"],["산포도","두 변수 간 상관관계 파악에 활용된다"]]},{"t":"tree","title":"재고 관리","root":"재고 관리","branches":[["주경로","주경로의 소요시간이 프로젝트의 최단완료시간이 된다"],["안전재고","불확실한 예상수요에 대비하기 위한 재고를 안전재고라고 한다"],["EOQ모형","재고수준이 재주문점에 도달하면 일정량만큼 주문한다"],["투빈(two-bin)시스템","수량이 많고 부피가 작은 저가품 관리에 많이 활용된다"]]}],"8":[{"t":"table","title":"가격전략","head":["전략","적합한 상황"],"rows":[["상대적 고가격전략","수요의 가격탄력성이 높지 않을 경우"],["스키밍 가격 전략","진입장벽이 높아 경쟁자의 시장 진입이 어려운 경우 · market-skimming"],["상대적 저가격전략","소비자들의 본원적 수요를 자극하고자 하는 경우"]]},{"t":"def","term":"가격 결정","text":"기업의 마케팅 목표 및 마케팅 믹스와의 조화를 고려하여 수립할 필요성이 있다"}],"9":[{"t":"table","title":"투자안 평가방법","head":["방법","내용"],"rows":[["회수기간법","PBP(Pay Back Period) · 투자원금을 회수하는 기간만을 고려하여 투자 안을 평가하는 방법"],["내부수익률법","IRR(Internal Rate of Return) · 내부수익률이 투자안의 요구수익률보다 높은지의 여부에 따라 투자안을 평가하는 방법"],["수익성지수법","PI(Profitability Index) · 투자안의 현금흐름을 고려하여 투자안을 평가 하는 방법"],["회계적이익률법","ARR(Account Rate of Return) · 회계처리방법의 선택에 따라 투자 안의 평가결과가 달라질 수 있다"]]}],"10":[{"t":"tree","title":"통합정보시스템","root":"자재, 회계, 구매, 생산, 판매, 인사 등 기업 내 업무의 통합정보시스템","branches":[["데이터 일원화","기업 내 각 부문의 데이터를 일원화하여 관리함으로써 경영자원을 계획적이고 효율적으로 운영하도록 해 준다"],["선진 프로세스","선진 프로세스를 내장하고 있는 패키지 도입 시 기업의 업무처리 방식을 최적화하는 데 도움이 될 수 있다"],["업무통합","수주처리에서 출하 및 회계처리까지 일련의 업무통합으로 고객 요구에 신속하고 정확 하게 대응할 수 있다"]]},{"t":"tree","title":"공급사슬관리","root":"자재 조달에서 제조, 판매, 고객까지 물류 및 정보 흐름을 최적화하는 것","branches":[["정보공유","정보공유를 토대로 공급업체, 제조업체, 유통업체 및 소비자를 유기적으로 연결하여 통합적으로 관리하는 시스템을 말한다"],["물류 통합","내부 물류 흐름뿐만 아니라 외부 물류 흐름의 통합에도 초점을 두고 있다"],["확산 배경","인터넷을 비롯한 정보통신기술의 진전을 들 수 있다"]]},{"t":"def","term":"지식","text":"사람의 행동과 의사결정에 지침을 주는 본능, 지각, 아이디어, 규칙과 절차 등의 결합을 의미하며 개인의 자산이자 기업의 자원으로써 부가가치 창출에서 차지하는 역할이 커지 고 있다"},{"t":"vs","title":"암묵지와 형식지","cols":[{"name":"암묵지","items":["개인이 학습과 체험을 통해 쌓은 지식으로 문서화하기 어렵다"]},{"name":"형식지","items":["언어, 문자, 숫자의 형태로 존재하는 지식을 말한다"]}]}]};
